import random

def findKthLargest(nums, k):
    a = list(nums)
    while True:
        pivot = a[random.randrange(len(a))]
        greater = [x for x in a if x > pivot]
        equal = [x for x in a if x == pivot]
        if k <= len(greater):
            a = greater
        elif k <= len(greater) + len(equal):
            return pivot
        else:
            k -= len(greater) + len(equal)
            a = [x for x in a if x < pivot]
